{
  "segment_function": "Introduces the distinction between human activities in relation to the presence of others, contrasts the Greek political animal with the modern social animal, and outlines the Greek opposition between the private household and the public polis.",
  "claims": [
    {
      "claim": "Action is exclusively dependent upon the constant presence of others, whereas labor and work do not strictly require the company of other humans in the same manner.",
      "claim_type": "author_position",
      "supporting_excerpt": "All human activities are conditioned by the fact that men live together, but it is only action that cannot even be imagined outside the society of men. The activity of labor does not need the presence of others... Action alone is the exclusive prerogative of man; neither a beast nor a god is capable of it, and only action is entirely dependent upon the constant presence of others.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "The translation of Aristotle's zōon politikon as animal socialis or social man reflects a loss of the original Greek understanding of politics.",
      "claim_type": "author_position",
      "supporting_excerpt": "More than any elaborate theory, this unconscious substitution of the social for the political betrays the extent to which the original Greek understanding of politics had been lost.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "vita activa",
      "definition": "Human life in so far as it is actively engaged in doing something, rooted always in a world of men and man-made things."
    }
  ],
  "distinctions": [
    {
      "item_a": "zōon politikon",
      "item_b": "animal socialis",
      "distinction": "The substitution of social for political betrays a loss of the original Greek understanding of politics, conflating the natural companionship of the human species with political organization."
    },
    {
      "item_a": "idion (what is one's own)",
      "item_b": "koinon (what is communal)",
      "distinction": "Represents the sharp distinction in a citizen's life between private life and the communal bios politikos."
    }
  ]
}

